# coding: utf-8
from lesson_authoring import entry as E
M=[['拉丁 male 坏地 + volens 愿意、希望 → malevolens','盼着坏事发生、对人怀恶意'],['法语／拉丁相关形式 → 英语 malevolent','恶意的、怀有害人愿望的']]
W=[
E('malevolent','英 /məˈlevələnt/；美 /məˈlevələnt/','恶意的；恶毒的','不是无心让你难受，而是心里就盼你倒霉。','拉丁 male“坏地” + volens“希望、愿意”，通过法语与拉丁相关形式进入英语。male 这一成分不指英语的男性。',M,'a malevolent look 是带着恶意的眼神，a malevolent character 是怀着害人意图的角色。它比 unfriendly“冷淡、不友好”更重，强调想让对方受害；小说写反派或阴森力量时很常见。','a malevolent look；malevolent intentions；a malevolent force；malevolent behavior。','benevolent 是怀善意，malevolent 是怀恶意。malicious 也强调恶意，malevolent 更容易突出持续的敌意或狠毒性格。',('The villain watched them with a malevolent smile.','反派带着恶毒的笑容看着他们。'),('She sensed a malevolent intention behind the friendly words.','她从友好的话语背后察觉到了恶意。'),sources=['https://en.wiktionary.org/wiki/malevolent','https://www.etymonline.com/word/malevolent']),
E('malevolence','英 /məˈlevələns/；美 /məˈlevələns/','恶意、恶毒','心里不是单纯不喜欢，而是有想让别人受苦的敌意。','来自法语 malevolence、拉丁 malevolentia，接 malevolens“怀恶意的”；与 malevolent 是同族的历史名词，不只看作英语换词尾。',M[:1]+[['拉丁 malevolentia → 法语 malevolence → 英语 malevolence','怀恶意的状态 → 恶意、狠毒']],'speak with malevolence 是话中带有恶意，an act of malevolence 是出于恶意的行为。这个名词抽出动机，可能藏在礼貌表面下面；所以不是只看说话声音是否大。','with malevolence；an act of malevolence；pure malevolence；a hint of malevolence。','malevolence 关注害人的意愿，anger 是生气的情绪；生气不一定想害人，怀恶意的人也可能表面平静。',('There was no anger in his voice, only cold malevolence.','他声音里没有怒气，只有冰冷的恶意。'),('The story explores the difference between carelessness and malevolence.','这个故事探讨了粗心与恶意之间的区别。'),sources=['https://en.wiktionary.org/wiki/malevolence','https://www.etymonline.com/word/malevolence']),
E('voluptuous','英 /vəˈlʌptʃuəs/；美 /vəˈlʌptʃuəs/','丰腴性感的；给感官丰盛享受的','形体、触感或声音显得丰厚、柔美，带来浓烈的感官愉悦。','经法语 voluptueux 或直接接拉丁 voluptuosus，来自 voluptas“愉悦、享受”；voluptas 与 velle“愿意”的更远联系有不确定性。',[['拉丁 volup → voluptas','愉悦地 → 愉悦、享受'],['拉丁 voluptuosus → 法语 voluptueux／英语 voluptuous','充满感官享受的 → 丰腴性感、感官丰盛的']],'a voluptuous figure 常说丰腴而性感的身形；voluptuous music 可以形容浓郁柔美、让感官沉浸的音乐。两种用法都带审美或感官评价，不能把它当成中性的“体积大”或“胖”。','a voluptuous figure；voluptuous curves；voluptuous music；a voluptuous texture。','voluptuous 不是 voluminous“体积大、蓬松或篇幅多”。本词的直接来源是“愉悦”一支，与意愿词族的远层关系不能写成确定的英语派生。',('The painting depicts a woman with a voluptuous figure.','画中描绘了一位身形丰腴性感的女子。'),('The orchestra produced a rich, voluptuous sound.','乐团奏出了浓郁而富有感官美感的声音。'),sources=['https://www.etymonline.com/word/voluptuous','https://en.wiktionary.org/wiki/voluptuous'])]
